INSERT OR REPLACE INTO clunk_asset_reviews (id, workspace_id, asset_id, visual_runtime, player_facing, human_decision, note, evidence_json, reviewer_user_id) VALUES ('review-mk-mine-portal', 'ws-artemis-store', 'asset-mk-mine-portal', 'PASS', 'NOT_EVALUATED', 'NOT_EVALUATED', '빌드가 형상 계약(접지·단위 배율·바깥 향한 면·삼각형 예산·맞물림)을 측정으로 통과시켰고, 6각도 대조표를 렌더했습니다. 사람 판정은 아직입니다.', '{"source":"kit-mine-entrance","report":"outputs/kits/mine-entrance/build-report.json","qa":"tmp/kits/mine-entrance/qa/mine-portal.json","sweep":"outputs/visual-sweep/mine-portal.png"}', 'usr-artemis-store');
INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-portal', 'ws-artemis-store', 'asset-mk-mine-portal', 'mine-portal', '갱도 입구 목재 프레임', '산기슭에 낸 갱도 입구를 목재로 짠 것입니다. 기둥 사이가 2.60 m, 상인방 아래가 2.60 m 이고, 300 mm 각재 기둥이 돌 기초 위에 섰습니다. 안쪽 어둠은 두께 120 mm 짜리 판재입니다 — 검게 칠한 얇은 면이 아니라 실제로 두께가 있어서 옆에서 보아도 모서리가 있고, 뒷면 렌더를 켜지 않아도 사라지지 않습니다. 상인방은 프레임보다 양쪽으로 200 mm 씩 더 나와 있고, 그 위에 길이가 서로 다른 널판 일곱 장, 무릎 버팀목 넷, 이음매마다 띠쇠와 못이 들어 있습니다. 입구 양옆에는 파낸 돌더미가 있습니다. 크기 4.19 × 3.45 × 0.94 m, 삼각형 992개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
