INSERT OR REPLACE INTO clunk_asset_reviews (id, workspace_id, asset_id, visual_runtime, player_facing, human_decision, note, evidence_json, reviewer_user_id) VALUES ('review-mk-mine-support', 'ws-artemis-store', 'asset-mk-mine-support', 'PASS', 'NOT_EVALUATED', 'NOT_EVALUATED', '빌드가 형상 계약(접지·단위 배율·바깥 향한 면·삼각형 예산·맞물림)을 측정으로 통과시켰고, 6각도 대조표를 렌더했습니다. 사람 판정은 아직입니다.', '{"source":"kit-mine-entrance","report":"outputs/kits/mine-entrance/build-report.json","qa":"tmp/kits/mine-entrance/qa/mine-support.json","sweep":"outputs/visual-sweep/mine-support.png"}', 'usr-artemis-store');
INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-support', 'ws-artemis-store', 'asset-mk-mine-support', 'mine-support', '갱도 목재 지지대 세트', '갱도 안에서 되풀이해 놓는 목재 지지대 한 세트입니다. 다리 중심 사이 1.80 m, 다리 통과 높이 2.10 m 이고, 되풀이 간격은 1.20 m 로 이 키트의 직선 레일 한 칸 길이와 같습니다. 다리 머리마다 쐐기 두 개가 갓돌을 50 mm 들어 올리고 있고, 무릎 버팀목 넷과 갓돌 위로 뻗은 널판 넷이 붙어 있습니다. 뒤에 같은 세트를 1.20 m 간격으로 놓으면 이 널판이 다음 세트의 갓돌에 얹힙니다. 입구 프레임보다 한 치수 작게 만들었습니다 — 안으로 들어갈수록 좁아져야 굴로 읽힙니다. 크기 2.18 × 2.44 × 0.71 m, 삼각형 576개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
