INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-cart-ore', 'ws-artemis-store', 'asset-mk-mine-cart-ore', 'mine-cart-ore', '광석 실은 광차', '밀어서 옮기는 광차입니다. 궤간 0.600 m 로 이 키트의 레일 세 종류와 그대로 맞물립니다. 답면 반지름 130 mm, 플랜지가 답면보다 22 mm 아래로 내려와 있어서 바닥에 두면 플랜지로 서고, 0.088 m 들어 올리면 답면이 레일 머리(y = 0.110 m)에 닿습니다 — 빌드가 매번 측정하는데 틈이 0 mm 입니다. 몸통은 모서리 기둥 넷에 널판을 세 단씩 두르고 그 사이를 실제로 비워 둔 것이고, 쇠 띠는 네 조각을 못으로 박은 모양입니다. 바퀴 축 둘이 각각 노드로 나뉘어 있고 ''wheels_roll'' 동작(2.0초)이 그 둘을 한 바퀴 돌립니다 — 회전 채널만 쓰고 배율 채널은 없습니다. 광석은 구리·철·금 세 색으로 아홉 덩이에 결정면 셋을 얹었고, 위에서 내려다보아도 바닥이 비쳐 보이지 않도록 어두운 받침판을 깔았습니다. 광석은 ''ore_load'' 메시로 따로 있어 지우면 빈 광차가 됩니다. 검사 도구는 바퀴 메시와 쇠붙이 메시가 44 mm 겹친다고 알려 주는데, 축이 베어링을 지나는 자리라 그렇게 만든 것입니다. 크기 1.02 × 0.97 × 0.65 m, 삼각형 1,764개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
