INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-tool-rack', 'ws-artemis-store', 'asset-mk-mine-tool-rack', 'mine-tool-rack', '곡괭이·삽 거치대', '곡괭이와 삽을 세워 두는 거치대입니다. 받침목이 0.90 m, 가로대가 0.92 m 높이에 있고 쇠 걸이못 둘이 가로대에서 앞으로 나와 있습니다. 곡괭이 머리는 눈구멍과 양옆으로 뻗은 뾰족날 둘, 자루에 박은 쐐기까지 전부 지오메트리이고, 삽날은 두께 20 mm 짜리 판이라 옆에서 보아도 사라지지 않습니다. 두 도구 모두 제 최저점을 측정해 바닥에 앉혔기 때문에 뜨지도, 받침목을 뚫고 나가지도 않습니다. 도구는 ''tools'' 메시로 따로 있어 지우면 빈 거치대가 됩니다. 크기 0.90 × 1.15 × 0.34 m, 삼각형 508개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
