INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-rail-straight', 'ws-artemis-store', 'asset-mk-mine-rail-straight', 'mine-rail-straight', '직선 레일 (1.2 m)', '직선 레일 한 칸입니다. 길이 1.200 m, 궤간 0.600 m, 침목 세 개를 0.400 m 간격으로 놓았습니다. 두 칸을 이어 붙여도 침목 간격이 그대로 유지됩니다. 레일 머리 윗면은 y = 0.110 m 이고, 곡선·끝막이와 0 mm 차이입니다 — 세 칸 모두 같은 열두 점짜리 단면을 밀어 만들었습니다. 침목마다 레일당 못 두 개가 9 mm 솟아 있고, 옆에는 굵은 자갈이 놓여 있습니다. 크기 1.20 × 0.11 × 1.10 m, 삼각형 656개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
