INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-rail-curve', 'ws-artemis-store', 'asset-mk-mine-rail-curve', 'mine-rail-curve', '곡선 레일 (90도)', '90도 곡선 레일 한 칸입니다. 중심선 반지름 1.200 m, 궤간 0.600 m 이고 침목 다섯 개가 곡선을 따라 놓여 있습니다. 이음점은 모듈 원점 기준 (-0.600, -0.600) 과 (0.600, 0.600) 로 대각선에 대칭이라, 90도씩 돌려 놓아도 직선 칸과 만납니다. 레일 단면과 레일 머리 높이(y = 0.110 m)는 직선 칸과 같은 값입니다. 크기 1.95 × 0.11 × 1.62 m, 삼각형 1,388개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
