INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-rail-stop', 'ws-artemis-store', 'asset-mk-mine-rail-stop', 'mine-rail-stop', '레일 끝막이', '레일 끝막이입니다. 길이 0.600 m 로 직선 칸의 절반이고 이음점은 x = -0.300 m 한쪽뿐입니다. 레일은 x = 0.200 m 에서 끝나고 버팀목 앞면은 x = 0.210 m 이라, 광차가 들어오면 바퀴가 아니라 완충목이 나무에 먼저 닿습니다. 기둥 둘과 가로 버팀목, 이음매를 감은 띠쇠 둘이 들어 있습니다. 레일 머리 높이는 나머지 두 칸과 같습니다. 크기 0.71 × 0.42 × 1.09 m, 삼각형 584개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
