INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-ladder', 'ws-artemis-store', 'asset-mk-mine-ladder', 'mine-ladder', '갱도 나무 사다리', '갱도용 나무 사다리입니다. 길이 2.39 m, 바깥 폭 0.47 m, 가로살 8개를 0.28 m 간격으로 놓았습니다. 가로살은 36 mm 팔각 기둥으로 실제 지오메트리이고 양쪽 세로대에 15 mm 씩 물려 있어서, 옆에서 보든 뒤에서 보든 사다리로 보입니다. 세로대를 6도 기울여 벽에 기대 세우는 자세로 만들었고, 아래 네 칸에는 밟은 자리를 밝은 색으로 넣었습니다. 크기 0.47 × 2.39 × 0.29 m, 삼각형 560개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
