INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-lantern', 'ws-artemis-store', 'asset-mk-mine-lantern', 'mine-lantern', '기둥에 건 광부 랜턴', '기둥에 걸어 둔 광부용 랜턴입니다. 기둥 높이 1.80 m, 팔 길이 0.40 m 이고, 램프는 갈고리에 걸린 별도 노드(''lantern_body'')입니다. ''lantern_swing'' 동작(2.4초, 회전 채널만)에서 기둥과 팔은 가만히 있고 램프만 좌우로 흔들립니다. 유리 네 장은 두께 6 mm 짜리 실제 판이고 이 키트에서 가장 밝은 색값으로 칠해 가장 어두운 쇠 테와 맞붙여 두었습니다. 텍스처도 발광 맵도 없는 파일이므로 주변을 실제로 밝히지는 않습니다 — 밝아 보이는 것은 색값입니다. 크기 0.73 × 1.80 × 0.62 m, 삼각형 384개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
