INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-powder-keg', 'ws-artemis-store', 'asset-mk-mine-powder-keg', 'mine-powder-keg', '화약통', '발파용 화약통입니다. 배 지름 0.43 m, 높이 0.65 m 이고 널 10장의 색이 이음매마다 끊깁니다 — 통을 매끈하게 칠하면 나무 달걀로 보입니다. 테 세 줄은 각자 앉은 자리의 지름에 맞춰 8 mm 씩 솟아 있고, 머리판에는 마개와 심지가 붙어 있습니다. 이 키트는 텍스처를 쓰지 않으므로 통에 찍는 글자는 없습니다. 크기 0.43 × 0.65 × 0.41 m, 삼각형 404개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
