INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-rock-large', 'ws-artemis-store', 'asset-mk-mine-rock-large', 'mine-rock-large', '바위 (1.2 m)', '바위입니다. 폭 1.30 m, 높이 0.69 m. 덩어리 5개를 서로 물려 붙여 실루엣에 모서리가 생기게 했고, 꼭짓점을 좌표 해시로 밀어 어느 고리도 원이 아닙니다. 면 색도 면 중심 좌표에서 뽑으므로 어느 쪽에서 보아도 각이 집니다. 큰 것과 작은 것은 같은 모델을 키우고 줄인 것이 아니라 서로 다른 모델입니다 — 그래서 노드에 배율이 들어가지 않습니다. 크기 1.30 × 0.69 × 1.00 m, 삼각형 280개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
