INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-mine-ore-iron', 'ws-artemis-store', 'asset-mk-mine-ore-iron', 'mine-ore-iron', '철 광석 덩이', '철 광석 덩이입니다. 폭 0.41 m. 모암은 이 키트의 바위·자갈과 같은 돌 색이고, 결정면 여섯 개만 철 색(#6f7580)으로 칠했습니다. 세 가지 광석은 이 한 가지만 다릅니다 — 나란히 놓으면 서로 다른 돌이 아니라 같은 광산에서 나온 세 광석으로 보입니다. 결정은 절반 이상이 모암에 묻혀 있어 꽂아 둔 것처럼 보이지 않습니다. 크기 0.41 × 0.29 × 0.32 m, 삼각형 168개, 재질 1개, 텍스처 없음. 바닥 y = 0 에 맞춰 놓았고 어느 노드에도 배율이 들어가 있지 않습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
