INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-mk-kit-mine-entrance', 'ws-artemis-store', 'asset-mk-kit-mine-entrance', 'kit-mine-entrance', '광산 입구 키트 (16종)', '산기슭 광산 입구를 통째로 만드는 키트입니다. 부품 16종이 한 팔레트(12색), 한 축척(미터), 한 형태 언어로 만들어져 서로 어울립니다. 목재 네 색과 쇠 색은 코지 팜 세트의 색값을 그대로 가져왔으므로 농장 물건과 같은 세계로 읽힙니다. 맞물림은 숫자로 맞춰 두었습니다 — 궤간 0.600 m, 레일 머리 높이 y = 0.110 m 가 직선·곡선·끝막이 세 칸에서 0 mm 차이로 같고, 광차를 0.088 m 들어 올리면 답면이 레일 머리에 0 mm 틈으로 닿습니다. 지지대 반복 간격 1.20 m 는 직선 레일 한 칸 길이와 같습니다. 이 파일은 16종을 바닥 격자에 늘어놓은 한 장짜리 배치도입니다(갱도 입구 목재 프레임, 갱도 목재 지지대 세트, 빈 광차, 광석 실은 광차, 곡괭이·삽 거치대, 직선 레일 (1.2 m), 곡선 레일 (90도), 레일 끝막이, 갱도 나무 사다리, 기둥에 건 광부 랜턴, 화약통, 바위 (1.2 m), 바위 (0.6 m), 구리 광석 덩이, 철 광석 덩이, 금 광석 덩이). 크기 6.97 × 3.45 × 8.16 m, 파일에 저장된 삼각형 8,512개, 화면에 그려지는 삼각형 10,348개 — 광차 두 대가 몸통·쇠붙이·바퀴 메시 다섯 개를 공유하기 때문에 두 값이 다릅니다. 재질 5개, 텍스처 없음. 동작은 이 파일에 들어 있지 않습니다. 광차의 바퀴 회전과 랜턴의 흔들림은 각 부품 파일에 있습니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
